 void BurnDeath(string label,bool ignite,bool shouldBurn,Texture charcoal,bool survived=false,float threshold=0f,float directDamage=10f,string corpseName="Human_Dead"){
  var target=Make(label);var hpFsm=Metadata(target,"Health","Health");var hp=hpFsm.FsmVariables.FindFsmFloat("Health");hp.Value=5f;hp.UseVariable=true;Receiver(target,target);target.AddComponent<BoxCollider>();
