  var body=Make("CorpseBody");body.transform.SetParent(corpseTemplate.transform,false);var renderer=body.AddComponent<MeshRenderer>();var source=new Material(Shader.Find("Standard"));source.color=Color.white;renderer.sharedMaterial=source;
