  var fsm=new Fsm{Name="Health",Variables=hpFsm.FsmVariables};var death=FsmEvent.GetFsmEvent("death");
  var spawn=new List<FsmStateAction>();foreach(var prefab in new[]{corpseTemplate,lootTemplate})spawn.Add(new HutongGames.PlayMaker.Actions.CreateObject{gameObject=new FsmGameObject{Value=prefab},parent=new FsmGameObject(),spawnPoint=new FsmGameObject{Value=target},position=new FsmVector3{UseVariable=true},rotation=new FsmVector3{UseVariable=true},storeObject=output});
  fsm.States=new[]{new FsmState(fsm){Name="alive",Transitions=new[]{new FsmTransition{FsmEvent=death,ToState="dead"}},Actions=new FsmStateAction[]{new HutongGames.PlayMaker.Actions.FloatCompare{float1=hp,float2=new FsmFloat{Value=threshold},tolerance=new FsmFloat{Value=0},equal=threshold==0f?death:null,lessThan=death,everyFrame=true}}},new FsmState(fsm){Name="dead",Actions=spawn.ToArray()}};fsm.Events=new[]{death};fsm.StartState="alive";fsm.SaveActions();hpFsm.Fsm=fsm;fsm.Init(hpFsm);hpFsm.enabled=true;fsm.Start();
