  var applied=corpse==null?null:corpse.GetComponentInChildren<MeshRenderer>(true).sharedMaterial;
  Check(corpse!=null&&(shouldBurn?applied!=source&&applied.mainTexture==charcoal:applied==source),label+": only flame-attributed corpse receives charcoal texture");
  if(ignite&&shouldBurn){var burning=Status(target);Check(burning!=null&&(bool)Prop(burning,"Ending")&&ReferenceEquals(Field(burning,"endingCorpse"),corpse.transform),label+": actual native corpse capture transfers dying flames to its body");}
  Check(renderer.sharedMaterial==source&&source.mainTexture==null&&source.color==Color.white,label+": shared/template materials remain unchanged");
  if(shouldBurn&&charcoal!=null&&applied!=null)Check(applied.color.r>applied.color.g*4f&&applied.color.r>applied.color.b*4f,label+": pale charcoal cracks tint dark flesh-red without changing shared texture");
  Check(loot!=null&&output.Value==loot&&loot.GetComponent<MeshRenderer>().sharedMaterial==source,label+": native loot output overwrite stays untouched");
  if(shouldBurn&&applied!=null&&applied!=source){Check((charcoal!=null?applied.mainTextureScale.x<.5f:applied.color.r<.2f)&&Near(applied.GetFloat("_Glossiness"),0f),label+": dark charcoal atlas region or safe matte tint without glowing embers");}
  if(corpse!=null)DestroyImmediate(corpse);if(loot!=null)DestroyImmediate(loot);DestroyImmediate(source);
 }
