 }
 void Ramp(int fps){FsmFloat hp;var root=Enemy("Ramp "+fps,out hp);hp.Value=1000f;Touch(root,.000001f,0f);var status=Status(root);for(int i=1;i<=fps*4;i++)Touch(root,1f/fps,i/(float)fps);Logger.LogInfo("Ramp "+fps+": stacks="+Prop(status,"Stacks")+"; damage="+(1000f-hp.Value)+"; credit="+Field(status,"contactSeconds"));Check((int)Prop(status,"Stacks")==5,"contact ramp reaches maximum at four seconds at "+fps+" FPS");Check(Near(1000f-hp.Value,100f,.05f),"native integrated burn damage is time-based at "+fps+" FPS");}
 void Geometry(){FsmFloat hp;var root=Enemy("Geometry",out hp);root.transform.position=new Vector3(0,-.063f,3);Physics.SyncTransforms();Set(pack,"flameIgniteFrame",-1);Call(pack,"IgniteFlameEnemies",Vector3.zero,Vector3.forward,4f,.1f);var status=Status(root);Check(status!=null,"production widening flame geometry ignites accepted enemy");float charge=Convert.ToSingle(Field(status,"contactSeconds"));Call(pack,"IgniteFlameEnemies",Vector3.zero,Vector3.forward,4f,.1f);Check(Near(Convert.ToSingle(Field(status,"contactSeconds")),charge,.00001f),"repeated render contact cannot add another charge in one frame");Set(pack,"flamePaidDamage",7f);Call(pack,"DamageFlameEnemies",Vector3.zero,Vector3.forward,4f);Check(Near(hp.Value,9993f)&&!(bool)Field(pack,"flameIgniteContactsReady"),"same-frame contact cache feeds exactly one native paid damage event");}
 void Edges(){
  FsmFloat killedHp;var killed=Enemy("KilledWhileRefreshing",out killedHp);killedHp.Value=5f;Touch(killed,.01f,0f);var ks=Status(killed);Touch(killed,.01f,1f);Check((bool)Prop(ks,"Ending")&&killedHp.Value<=0f,"contact refresh cannot restart a burn that just killed its actor");
  FsmFloat hp;var corpse=Enemy("Flexa_Dead(Clone)12",out hp);corpse.AddComponent<Rigidbody>().isKinematic=true;Touch(corpse,1f,0f);Check(Status(corpse)==null,"physical corpse cannot ignite even with residual positive Health");
  var unsupported=Make("OnlyMultipliedLimb");Metadata(unsupported,"Health","Health");var limb=Make("Head");limb.transform.SetParent(unsupported.transform,false);Receiver(limb,unsupported,3f);Touch(unsupported,1f,0f);Check(Status(unsupported)==null,"missing native root receiver never falls back to head multiplier or direct Health writes");
  var gap=Enemy("ContactGap",out hp);Touch(gap,.2f,0f);var gs=Status(gap);Advance(gs,5f);Check((int)Prop(gs,"Stacks")==1,"time away from flame does not charge stacks");Touch(gap,.8f,5f);Check((int)Prop(gs,"Stacks")==2,"only accumulated actual contact adds the next stack after a gap");
  var moving=Enemy("MoveThenDestroy",out hp);Touch(moving,.01f,0f);var ms=Status(moving);Vector3 old=((Component)ms).transform.position;moving.transform.position+=Vector3.right*2;Call(ms,"LateUpdate");Check(Near((((Component)ms).transform.position-old).x,2f),"owned fire follows its living actor");DestroyImmediate(moving);Advance(ms,.2f);Check((bool)Prop(ms,"Ending"),"destroyed enemy begins a safe detached fade");
  var savedMaterial=Field(pack,"flameIgniteMaterial");Set(pack,"flameIgniteMaterial",null);Set(pack,"nextIgniteMaterial",Time.unscaledTime+100f);var delayed=Enemy("DestroyedBeforeMaterialReady",out hp);Touch(delayed,.01f,0f);var delayedStatus=Status(delayed);DestroyImmediate(delayed);Set(pack,"flameIgniteMaterial",savedMaterial);Set(pack,"nextIgniteMaterial",0f);Advance(delayedStatus,.2f);Check((bool)Prop(delayedStatus,"Ending")&&Field(delayedStatus,"particles")==null,"late material availability cannot create fire on a destroyed or ending actor");
  var damage=Field(pack,"flameIgniteDamage");var maximum=Field(pack,"flameIgniteStackCount");var interval=Field(pack,"flameIgniteInterval");var duration=Field(pack,"flameIgniteDuration");damage.GetType().GetProperty("Value").SetValue(damage,7.5f,null);maximum.GetType().GetProperty("Value").SetValue(maximum,3,null);interval.GetType().GetProperty("Value").SetValue(interval,.5f,null);duration.GetType().GetProperty("Value").SetValue(duration,2f,null);
  var configured=Enemy("Configured",out hp);Touch(configured,.000001f,0f);var cs=Status(configured);Touch(configured,.5f,.5f);Touch(configured,.5f,1f);Check((int)Prop(cs,"Stacks")==3&&Near((float)Prop(cs,"DamagePerSecond"),22.5f),"damage, maximum and interval settings control native burn stacks");Advance(cs,3f);Check((bool)Prop(cs,"Ending"),"configured burn duration applies after latest contact");
  damage.GetType().GetProperty("Value").SetValue(damage,10f,null);maximum.GetType().GetProperty("Value").SetValue(maximum,5,null);interval.GetType().GetProperty("Value").SetValue(interval,1f,null);duration.GetType().GetProperty("Value").SetValue(duration,10f,null);
  int blood=0;foreach(var go in Resources.FindObjectsOfTypeAll<GameObject>())if(go.name=="Chainsaw.NativeBloodHit")blood++;Check(blood==0,"burn damage never instantiates pack melee blood spray");
 }
 void Horde(){
  var origin=new Vector3(1000,0,0);for(int i=0;i<24;i++){FsmFloat hp;var root=Enemy("Horde "+i,out hp);root.layer=10;root.transform.position=origin+new Vector3((i%3-1)*.08f,-.063f,2.5f+i*.04f);root.GetComponent<BoxCollider>().size=new Vector3(.12f,.35f,.12f);}
  Physics.SyncTransforms();Call(pack,"CollectFlameEnemyContacts",origin,Vector3.forward,4f);Check(((IDictionary)Field(pack,"flameEnemyContacts")).Count==24,"native horde collector retains every shared actor");
  var watch=System.Diagnostics.Stopwatch.StartNew();for(int i=0;i<100;i++)Call(pack,"CollectFlameEnemyContacts",origin,Vector3.forward,4f);watch.Stop();Timing("TIMING: 24 native actors, collector mean="+(watch.Elapsed.TotalMilliseconds/100).ToString("F4")+" ms (isolated query, not whole-game FPS)");
  Set(pack,"flameIgniteFrame",-1);Call(pack,"IgniteFlameEnemies",origin,Vector3.forward,4f,.01f);watch.Restart();for(int i=0;i<100;i++){Set(pack,"flameIgniteFrame",-1);Call(pack,"IgniteFlameEnemies",origin,Vector3.forward,4f,.01f);}watch.Stop();Timing("TIMING: 24 native actors, warm ignite contact mean="+(watch.Elapsed.TotalMilliseconds/100).ToString("F4")+" ms");
  var statuses=new List<object>();foreach(var go in owned)if(go!=null&&go.name.StartsWith("Horde "))statuses.Add(Status(go));watch.Restart();for(int i=1;i<=100;i++)foreach(var status in statuses)Advance(status,i/60f);watch.Stop();Timing("TIMING: 24 native actors, burn/visual advance mean="+(watch.Elapsed.TotalMilliseconds/100).ToString("F4")+" ms per simulated frame");
 }
}




